package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class CommutativeArithmeticTest {
 @Test public void publicOperandsOrderAndBoundaryResultsAreIndependentOfKeys(){Checker c=new Checker();for(String id:List.of(CommutativeArithmetic.ADD,CommutativeArithmetic.MUL))for(int[] pair:List.of(new int[]{0,0},new int[]{0,1000000},new int[]{1,999999},new int[]{123,456},new int[]{1000,1000},new int[]{1000000,0})){int a=pair[0],b=pair[1];long value=id.equals(CommutativeArithmetic.ADD)?(long)a+b:(long)a*b;if(value>1000000)continue;Question q=CommutativeArithmetic.make(id,a,b);q.answers=new String[]{"poison"};q.expression="poison";List<String> answers=List.of(""+b,""+a,""+value);assertTrue(c.check(q,List.of(),answers).correct());for(int i=0;i<3;i++){List<String> wrong=new ArrayList<>(answers);wrong.set(i,""+(Long.parseLong(wrong.get(i))+1));assertEquals(i,c.check(q,List.of(),wrong).index);}HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(3,h.size());for(int i=0;i<3;i++)assertTrue(h.step(i).accepts(answers.get(i)));assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}assertNull(CommutativeArithmetic.read(new Question(CommutativeArithmetic.ADD,"1000000 + 1 = □ + □\n두 수의 순서를 바꿔 빈칸과 계산값을 쓰세요.","")));}
 @Test public void smallDomainsAreCompleteAndRepeatOnlyAfterAllValidConditions(){for(String id:List.of(CommutativeArithmetic.ADD,CommutativeArithmetic.MUL)){CurriculumLimits l=new CurriculumLimits("minGiven=0;maxGiven=3;maxResult=3;nonnegative=true");int expected=0;for(int a=0;a<=3;a++)for(int b=0;b<=3;b++)if((id.equals(CommutativeArithmetic.ADD)?a+b:a*b)<=3)expected++;Generator g=new Generator(new Random(264));List<String> recent=new ArrayList<>();for(int i=0;i<expected;i++){Question q=g.next(id,recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertNotNull(CommutativeArithmetic.read(q));}assertEquals(recent.get(0),g.next(id,recent,false,l).signature());}}
 @Test public void ordinaryGradeSixCoversLargeInputsWithoutQuestionPools(){String pack="na-nied-primary-2024-v1";Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,pack);Generator gen=new Generator(new Random(264));for(String id:List.of(CommutativeArithmetic.ADD,CommutativeArithmetic.MUL)){assertTrue(GlobalCurriculum.pack(p).inGrade(id,6));assertFalse(Curriculum.inCurriculum(Catalog.get(id),2022));CurriculumLimits l=GlobalCurriculum.limits(pack,id,6);List<String> recent=new ArrayList<>();boolean large=false;for(int i=0;i<100;i++){Question q=gen.next(id,recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());long[] n=CommutativeArithmetic.read(q);assertTrue(n[2]<=1000000);large|=Math.max(n[0],n[1])>=100000;}assertTrue(large);}}
}
